local u=function(s)local L,x=s[#s],""for G=1,#L,1 do x=x..L[s[G]]end return x end local function s(s)local L=0 while s~=1 do if s%2==0 then s=s/2 else s=3*s+1 end L=L+1 end return L end local function L(s)if s<0 then return"negative"elseif s==0 then return"zero"elseif s<10 then return"small"elseif s<100 then return"medium"else return"large"end end local function x(s)local L for x=2,s,1 do if s%x==0 then L=x break end end return L end local function G(s)local L=0 repeat L=L+s%10 s=math.floor(s/10)until s==0 return L end local function y(s)local L="start"local x={}for G=1,#s,1 do local y=s:sub(G,G)if L=="start"then if y=="a"then L="seenA"end elseif L=="seenA"then if y=="b"then L="seenAB"elseif y~="a"then L="start"end elseif L=="seenAB"then L=(y=="c")and"accept"or"start"end x[#x+1]=L end return L,table.concat(x,">")end for L,x in ipairs({6,7,27})do print("collatz("..(x..(") = "..s(x))))end for s,x in ipairs({-5,0,7,42;1000})do print(x..(" is "..L(x)))end print(x(91),x(97),G(98765))print(y("xxabcab"))print(y("aabx"))